/* =====================================================================
   Shared GLSL
   ===================================================================== */
const GLSL_COMMON = `
  float h13( vec3 p ) {
    p = fract( p * 0.1031 );
    p += dot( p, p.zyx + 31.32 );
    return fract( ( p.x + p.y ) * p.z );
  }
  vec3 h33( vec3 p ) {
    p = fract( p * vec3( 0.1031, 0.1030, 0.0973 ) );
    p += dot( p, p.yxz + 33.33 );
    return fract( ( p.xxy + p.yxx ) * p.zyx );
  }
  float vnoise3( vec3 p ) {
    vec3 i = floor( p );
    vec3 f = fract( p );
    vec3 u = f * f * ( 3.0 - 2.0 * f );
    float a000 = h13( i );
    float a100 = h13( i + vec3( 1.0, 0.0, 0.0 ) );
    float a010 = h13( i + vec3( 0.0, 1.0, 0.0 ) );
    float a110 = h13( i + vec3( 1.0, 1.0, 0.0 ) );
    float a001 = h13( i + vec3( 0.0, 0.0, 1.0 ) );
    float a101 = h13( i + vec3( 1.0, 0.0, 1.0 ) );
    float a011 = h13( i + vec3( 0.0, 1.0, 1.0 ) );
    float a111 = h13( i + vec3( 1.0, 1.0, 1.0 ) );
    return mix( mix( mix( a000, a100, u.x ), mix( a010, a110, u.x ), u.y ),
                mix( mix( a001, a101, u.x ), mix( a011, a111, u.x ), u.y ), u.z );
  }
  vec3 worley3( vec3 p ) {
    vec3 ip = floor( p );
    vec3 fp = fract( p );
    float f1 = 9.0;
    float f2 = 9.0;
    float id = 0.0;
    for ( int k = -1; k <= 1; k++ ) {
      for ( int j = -1; j <= 1; j++ ) {
        for ( int i = -1; i <= 1; i++ ) {
          vec3 g = vec3( float( i ), float( j ), float( k ) );
          vec3 dd = g + h33( ip + g ) - fp;
          float q = dot( dd, dd );
          if ( q < f1 ) { f2 = f1; f1 = q; id = h13( ip + g + 17.17 ); }
          else if ( q < f2 ) { f2 = q; }
        }
      }
    }
    return vec3( sqrt( f1 ), sqrt( f2 ), id );
  }
  vec3 hue3( float h ) {
    return clamp( abs( fract( h + vec3( 0.0, 2.0 / 3.0, 1.0 / 3.0 ) ) * 6.0 - 3.0 ) - 1.0, 0.0, 1.0 );
  }
  vec3 rotAA( vec3 v, vec3 k, float ang ) {
    float c = cos( ang );
    float s = sin( ang );
    return v * c + cross( k, v ) * s + k * dot( k, v ) * ( 1.0 - c );
  }
