/* =====================================================================
   Conical lead / copper bullet: analytic plastic mushrooming
   ===================================================================== */
const CONTACT_W = DROP_OFFSET.clone();   // bulb tip (a = 0) in world space
const V_B = 5.5;                          // apparent approach speed (units / sim-s)
const B_TAU = 0.085;                      // crush time constant
const DMAX = 0.52;                        // crushed length at saturation
const BSEG = 40;
const BULLET_CTRL = [
  [0.000, 0.000], [0.000, 0.024], [0.005, 0.038], [0.014, 0.048],
  [0.06, 0.068], [0.12, 0.094], [0.18, 0.120], [0.24, 0.146], [0.28, 0.160],
  [0.31, 0.168], [0.34, 0.172], [0.40, 0.174], [0.46, 0.174], [0.48, 0.166], [0.51, 0.166], [0.53, 0.174],
  [0.60, 0.174], [0.66, 0.172], [0.70, 0.166], [0.73, 0.150], [0.742, 0.12], [0.745, 0.06], [0.745, 0.0]
];
const BP = (function resample(ctrl, n) {
  const segL = [0];
