    { n: 170, kind: 0, t0: T_HIT, t1: T_HIT + 0.07, at: CONTACT_W, speed: [4, 12], axial: true, life: [0.2, 0.6], size: [0.012, 0.024] },
    { n: 110, kind: 1, t0: T_SNIP, t1: T_SNIP + 0.04, at: P_CUT_W, speed: [1.2, 4.5], axial: false, life: [0.15, 0.5], size: [0.010, 0.022] },
    { n: 160, kind: 1, t0: T_FRONT1, t1: T_FRONT1 + 0.05, at: BULB_C_L.clone().add(DROP_OFFSET), speed: [2.5, 7.5], axial: false, life: [0.15, 0.55], size: [0.010, 0.022] }
  ];
  const N = groups.reduce((s, g) => s + g.n, 0);
  const pos = new Float32Array(N * 3), vel = new Float32Array(N * 3), prm = new Float32Array(N * 4), kind = new Float32Array(N);
  const v = new V3();
  let i = 0;
  groups.forEach((g) => {
    for (let k = 0; k < g.n; k++, i++) {
      g.at.toArray(pos, i * 3);
      if (g.axial) {
        const ph = rand() * Math.PI * 2, sp = rr(g.speed[0], g.speed[1]);
        v.set(rr(0.5, 3.5), Math.cos(ph) * sp, Math.sin(ph) * sp);
      } else {
        randUnit(v).multiplyScalar(rr(g.speed[0], g.speed[1]));
      }
      v.toArray(vel, i * 3);
      prm[i * 4] = rr(g.t0, g.t1);
      prm[i * 4 + 1] = rr(2.0, 4.5);
      prm[i * 4 + 2] = rr(g.life[0], g.life[1]);
      prm[i * 4 + 3] = rr(g.size[0], g.size[1]);
      kind[i] = g.kind;
    }
