/* =====================================================================
   Deterministic state evaluation: everything below is a pure function
   of simTime (no accumulated state, no frame counters, no wall clock)
   ===================================================================== */
const TIP_V = new V3().copy(P_CUT_W).normalize().multiplyScalar(0.7).add(new V3(0.35, 0.55, 0.25));
const TIP_AXIS = new V3(0.3, 0.2, 1).normalize();

function stressVis(t) {
  let s = 0.26;
  if (t > T_HIT) s += 0.25 * Math.exp(-(t - T_HIT) / 0.5);
  const u = (t - T_CLEAR) / (T_SNIP - T_CLEAR);
  if (u > 0 && u < 1) s += 0.42 * Math.pow(Math.sin(Math.PI * u), 2) * (0.8 + 0.2 * Math.cos(u * Math.PI * 5));
  if (t > T_SNIP) s += 0.25 * smooth(T_SNIP, T_SNIP + 0.2, t);
  return s;
}
function stressMod(t) {
  const u = (t - T_CLEAR) / (T_SNIP - T_CLEAR);
  return (u > 0 && u < 1) ? 1 + 0.16 * Math.sin(Math.PI * u) * Math.sin(u * Math.PI * 4) : 1;
}

const _w = new V3(), _fc = new THREE.Color();
function updateDrop(t) {
  // rigid recoil + damped ringing of the clamped drop after the impact
  let rx = 0, ry = 0;
  if (t > T_HIT) {
    const d = t - T_HIT;
    rx = -0.03 * Math.exp(-2.8 * d) * Math.sin(2 * Math.PI * 3.2 * d);
    ry = 0.006 * Math.exp(-3.5 * d) * Math.sin(2 * Math.PI * 5.1 * d);
  }
  dropRoot.position.set(DROP_OFFSET.x + rx, DROP_OFFSET.y + ry, DROP_OFFSET.z);

  const gu = glassUniforms;
  gu.uTime.value = t;
  gu.uFrontA.value = frontAt(t);
  gu.uFrontOn.value = t >= T_SNIP ? 1 : 0;
  gu.uFrontGlow.value = t < T_SNIP ? 0 : (t < T_FRONT0 ? 0.45 * smooth(T_SNIP, T_SNIP + 0.1, t) : (t < T_FRONT1 + 0.05 ? 1.0 : 0.0));
  gu.uStress.value = stressVis(t);
  gu.uStressMod.value = stressMod(t);
  gu.uRingT.value = (t > T_HIT && t < T_HIT + 2.5) ? t - T_HIT : -1;
  gu.uSqueeze.value = t < T_SNIP ? smooth(3.45, T_SNIP, t) : Math.exp(-(t - T_SNIP) / 0.05);
  gu.uSnip.value = t >= T_SNIP ? Math.exp(-(t - T_SNIP) / 0.12) : 0;
  gu.uBulbCW.value.copy(BULB_C_L).add(dropRoot.position);

  // severed tail tip: tumbles away ballistically
  if (t < T_SNIP) {
    tipPivot.position.copy(P_CUT_L);
    tipPivot.quaternion.identity();
  } else {
    const d = t - T_SNIP;
    tipPivot.position.set(P_CUT_L.x + TIP_V.x * d, P_CUT_L.y + TIP_V.y * d - 1.8 * d * d, P_CUT_L.z + TIP_V.z * d);
    tipPivot.quaternion.setFromAxisAngle(TIP_AXIS, 2.4 * d + 0.6 * d * d);
  }
  glassTip.visible = t < T_SNIP + 2.6;
}

function setGlow(sp, on, x, y, z, sx, sy, op) {
  sp.visible = on && op > 0.002;
  if (!sp.visible) return;
  sp.position.set(x, y, z);
  sp.scale.set(sx, sy, 1);
  sp.material.opacity = op;
}
function updateFx(t) {
  // single analytic flash light shared by standard + custom shaders
  let I = 0;
  _w.set(0, 0, 0);
  if (t >= T_HIT && t < T_HIT + 0.8) {
    I = 4.0 * Math.exp(-(t - T_HIT) / 0.07);
    _w.copy(CONTACT_W).add(new V3(0.15, 0, 0.2));
    _fc.setRGB(1.0, 0.78, 0.55);
  } else if (t >= T_SNIP && t < T_FRONT0) {
    I = 6.0 * Math.exp(-(t - T_SNIP) / 0.09) + 0.5 * smooth(T_SNIP, T_FRONT0, t);
    _w.copy(P_CUT_W);
    _fc.setRGB(0.72, 0.86, 1.0);
  } else if (t >= T_FRONT0 && t < T_FRONT1) {
    I = 1.7;
    spineSample(clamp(frontAt(t), 0, A_CUT), _w);
    _w.add(dropRoot.position);
    _fc.setRGB(0.66, 0.84, 1.0);
  } else if (t >= T_FRONT1 && t < T_FRONT1 + 1.2) {
    I = 7.0 * Math.exp(-(t - T_FRONT1) / 0.12) + 0.4 * Math.exp(-(t - T_FRONT1) / 0.6);
    _w.copy(BULB_C_L).add(dropRoot.position);
    _fc.setRGB(0.80, 0.90, 1.0);
  }
  fxLight.position.copy(_w);
  fxLight.color.copy(_fc);
  fxLight.intensity = I;
  glassUniforms.uFxPos.value.copy(_w);
  glassUniforms.uFxCol.value.set(_fc.r * I, _fc.g * I, _fc.b * I);

  // impact flash
  const di = t - T_HIT;
  setGlow(gImpact, di >= 0 && di < 0.45, CONTACT_W.x + 0.05, CONTACT_W.y, CONTACT_W.z + 0.1,
    0.5 + 2.2 * clamp01(di / 0.12), 0.5 + 2.2 * clamp01(di / 0.12), di >= 0 ? 0.95 * Math.exp(-di / 0.07) : 0);
  // bullet speed streak
  const bx = CONTACT_W.x + V_B * (T_HIT - t);
  setGlow(gStreak, t < T_HIT, bx + 0.55, CONTACT_W.y, CONTACT_W.z, 2.6, 0.2, 0.32 * smooth(0, 0.2, t));
  // triboluminescence at the cut
  const ds = t - T_SNIP;
  const snipOp = ds >= 0 ? Math.exp(-ds / 0.09) : 0;
  setGlow(gSnip, ds >= 0 && ds < 0.6, P_CUT_W.x, P_CUT_W.y, P_CUT_W.z, 0.3 + 1.3 * clamp01(ds / 0.08), 0.3 + 1.3 * clamp01(ds / 0.08), snipOp);
  setGlow(gSnipStar, ds >= 0 && ds < 0.4, P_CUT_W.x, P_CUT_W.y, P_CUT_W.z, 1.6 + 1.2 * clamp01(ds / 0.1), 1.6 + 1.2 * clamp01(ds / 0.1), 0.9 * snipOp);
  // racing front glow
  if (t >= T_SNIP && t < T_FRONT1 + 0.04) {
    const af = clamp(frontAt(t), 0, A_CUT);
    spineSample(af, _w);
    _w.add(dropRoot.position);
    const r = radiusAt(af);
    const op = t < T_FRONT0 ? 0.25 * smooth(T_SNIP, T_SNIP + 0.15, t) : 0.6;
    setGlow(gFront, true, _w.x, _w.y, _w.z, 0.35 + 2.4 * r, 0.35 + 2.4 * r, op);
  } else {
    gFront.visible = false;
  }
  // disintegration burst
  const db = t - T_FRONT1;
  _w.copy(BULB_C_L).add(dropRoot.position);
  setGlow(gBurst, db >= 0 && db < 0.8, _w.x, _w.y, _w.z, 1.2 + 4.0 * clamp01(db / 0.25), 1.2 + 4.0 * clamp01(db / 0.25), db >= 0 ? Math.exp(-db / 0.12) : 0);
}

function renderAt(simT) {
  const t = clamp(Number.isFinite(simT) ? simT : 0, 0, DURATION);
  updateDrop(t);
  updateBullet(t);
  updateSpall(t);
  updateNippers(t);
  updateFx(t);
  shardUniforms.uTime.value = t;
  dustUniforms.uTime.value = t;
  sparkUniforms.uTime.value = t;
  renderer.render(scene, camera);
}
window.renderAt = renderAt;

/* ---------- camera: fixed 35deg (85mm-equivalent), locked on the Z axis ---------- */
function fitCamera() {
  const tanH = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
  const FILL = 0.62;
  const dH = (BB_SIZE.y / 2) / (FILL * tanH);
  const dW = (BB_SIZE.x / 2) / (FILL * tanH * camera.aspect);
  const d = Math.max(dH, dW) + BB_SIZE.z / 2;
  camera.position.set(0, 0, d);
  camera.lookAt(0, 0, 0);
}
const _db = new THREE.Vector2();
function onResize() {
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  camera.aspect = window.innerWidth / Math.max(window.innerHeight, 1);
  fitCamera();
  camera.updateProjectionMatrix();
  renderer.getDrawingBufferSize(_db);
  pointScale.value = _db.y / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
}
onResize();
window.addEventListener('resize', () => { onResize(); renderAt(simTime); });

