/* =====================================================================
   Playback state machine: COUNTDOWN, PLAYING, PAUSED, REFIRE_HOLD, ENDED
   ===================================================================== */
const elCountdown = document.getElementById('countdown');
const btnToggle = document.getElementById('btn-toggle');
const btnRefire = document.getElementById('btn-refire');
const iconPause = document.getElementById('icon-pause');
const iconPlay = document.getElementById('icon-play');
const scrubber = document.getElementById('scrubber');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

let state = 'INIT';
let simTime = 0;
let playbackSpeed = 1.0;
let countdownStart = 0;
let holdStart = 0;
let lastNow = 0;

function setPlayingIcons(playing) {
  iconPause.style.display = playing ? 'block' : 'none';
  iconPlay.style.display = playing ? 'none' : 'block';
  btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function hideCountdown() {
  elCountdown.style.display = 'none';
  elCountdown.textContent = '';
}
function showCountdown(txt) {
  if (elCountdown.style.display !== 'block') elCountdown.style.display = 'block';
  if (elCountdown.textContent !== txt) elCountdown.textContent = txt;
}

btnToggle.addEventListener('click', () => {
  if (state === 'PLAYING') {
    state = 'PAUSED';
    setPlayingIcons(false);
  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD' || state === 'INIT') {
    hideCountdown();
    simTime = 0;
    scrubber.value = '0';
    state = 'PAUSED';
    setPlayingIcons(false);
    renderAt(simTime);
  } else if (state === 'PAUSED') {
    state = 'PLAYING';
    setPlayingIcons(true);
  } else if (state === 'ENDED') {
    hideCountdown();
    simTime = 0;
    scrubber.value = '0';
    state = 'PLAYING';
    setPlayingIcons(true);
    renderAt(simTime);
  }
});

btnRefire.addEventListener('click', () => {
  hideCountdown();
  simTime = 0;
  scrubber.value = '0';
  renderAt(simTime);
  setPlayingIcons(true);
  state = 'REFIRE_HOLD';
  holdStart = performance.now();
});

pills.forEach((pill) => {
  pill.addEventListener('click', () => {
    playbackSpeed = parseFloat(pill.getAttribute('data-speed'));
    pills.forEach((p) => {
      const on = p === pill;
      p.classList.toggle('is-active', on);
      p.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  });
});

scrubber.addEventListener('input', () => {
  if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD' || state === 'INIT') hideCountdown();
  const v = parseFloat(scrubber.value);
  simTime = clamp(Number.isFinite(v) ? v : 0, 0, DURATION);
  state = 'PAUSED';
  setPlayingIcons(false);
  renderAt(simTime);
});

function frame() {
  requestAnimationFrame(frame);
  const now = performance.now();
  let dt = (now - lastNow) / 1000;
  lastNow = now;
  if (!(dt > 0)) dt = 0;
  if (dt > 0.1) dt = 0.1;

  if (state === 'COUNTDOWN') {
    const ce = Math.max(0, (now - countdownStart) / 1000);
    if (ce < 3) { showCountdown(String(3 - Math.floor(ce))); return; }
    hideCountdown();
    state = 'PLAYING';
    setPlayingIcons(true);
    simTime = 0;
    dt = Math.min(ce - 3, 0.1);
  } else if (state === 'REFIRE_HOLD') {
    const he = Math.max(0, (now - holdStart) / 1000);
    if (he < 1) return;
    state = 'PLAYING';
    simTime = 0;
    dt = Math.min(he - 1, 0.1);
  }
  if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    if (simTime >= DURATION) {
      simTime = DURATION;
      scrubber.value = DURATION.toFixed(3);
      renderAt(simTime);
      state = 'ENDED';
      setPlayingIcons(false);
      return;
    }
    scrubber.value = simTime.toFixed(3);
    renderAt(simTime);
  }
}

/* ---------- boot: compile, render the resting scene, start the countdown ---------- */
renderer.compile(scene, camera);
renderAt(0);
requestAnimationFrame(() => {
  lastNow = performance.now();
  if (state === 'INIT') {
    state = 'COUNTDOWN';
    countdownStart = lastNow;
    showCountdown('3');
  }
  requestAnimationFrame(frame);
});

