(function () {
  var qs = new URLSearchParams(location.search);
  var bootMs = (performance.now() - window.__t0).toFixed(0);
  var times = (qs.get('t') || '0').split(',').map(Number);
  var cols = Number(qs.get('cols') || Math.ceil(Math.sqrt(times.length)));
  var stage = document.getElementById('stage');
  var scrub = document.getElementById('scrubber');
  var W = stage.width, H = stage.height;
  var scale = Number(qs.get('scale') || (times.length > 1 ? 1 / cols : 1));
  var tw = Math.round(W * scale), th = Math.round(H * scale);
  var rows = Math.ceil(times.length / cols);
  var sheet = document.createElement('canvas');
  sheet.width = tw * cols; sheet.height = th * rows;
  var g = sheet.getContext('2d');
  var timings = [];
  var gl = null;
  try { gl = stage.getContext('webgl2') || stage.getContext('webgl'); } catch (e) {}
  times.forEach(function (t, i) {
    var x = (i % cols) * tw, y = Math.floor(i / cols) * th;
    var grd = g.createRadialGradient(x + tw / 2, y + th / 2, 0, x + tw / 2, y + th / 2, Math.hypot(tw, th) / 2);
    grd.addColorStop(0, '#161922'); grd.addColorStop(1, '#090a0f');
    g.fillStyle = grd; g.fillRect(x, y, tw, th);
    scrub.value = String(t);
    var t0 = performance.now();
    scrub.dispatchEvent(new Event('input', { bubbles: true }));
    if (gl) gl.finish();
    timings.push((performance.now() - t0).toFixed(1));
    g.drawImage(stage, x, y, tw, th);
    if (times.length > 1) { g.fillStyle = 'rgba(255,255,0,0.9)'; g.font = '14px monospace'; g.fillText('t=' + t, x + 6, y + 16); }
  });
  var img = document.createElement('img');
  img.src = sheet.toDataURL('image/png');
  img.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;object-fit:contain;z-index:' + (qs.get('ui') === '1' ? '40' : '1000') + ';background:#000';
