(function () {
  var $ = function (id) { return document.getElementById(id); };
  var cd = $('countdown'), sc = $('scrubber'), tg = $('btn-toggle'), rf = $('btn-refire');
  var ip = $('icon-pause'), ipl = $('icon-play');
  var pills = document.querySelectorAll('.speed-pill');
  var out = [];
  var fails = 0;
  function snap() {
    return 'cd=' + JSON.stringify(cd.style.display) + '/' + JSON.stringify(cd.textContent) + ' sc=' + sc.value + ' aria=' + tg.getAttribute('aria-label') +
      ' pause=' + (ip.style.display || '(def)') + ' play=' + (ipl.style.display || '(def)');
  }
  function check(label, cond) { if (!cond) fails++; out.push((cond ? 'ok   ' : 'FAIL ') + label + ' | ' + snap()); }
  function run(sec) { var n = Math.round(sec * 1000 / 16); for (var i = 0; i < n; i++) window.__pump(16); var rem = sec * 1000 - n * 16; if (rem > 0) window.__pump(rem); }
  var v = function () { return parseFloat(sc.value); };

  // 1) countdown
  check('before first rAF: countdown text 3', cd.textContent === '3');
  window.__pump(16);               // first rAF -> COUNTDOWN starts (elapsed 0)
  window.__pump(16);
  check('countdown 3 visible', cd.style.display === 'block' && cd.textContent === '3' && sc.value === '0');
  run(0.98);
  check('countdown 2 at ~1.0s', cd.textContent === '2' && sc.value === '0');
  run(1.0);
  check('countdown 1 at ~2.0s', cd.textContent === '1' && sc.value === '0');
  run(1.0);
  check('countdown hidden after 3s, playing', cd.style.display === 'none' && cd.textContent === '' && v() > 0 && v() < 0.1);
  run(1.0);
  check('playing ~1.0 after 1s', Math.abs(v() - 1.0) < 0.06 && tg.getAttribute('aria-label') === 'Pause');
  // 2) pause / resume
  tg.click();
  var p0 = v();
  run(0.5);
  check('paused holds time', v() === p0 && tg.getAttribute('aria-label') === 'Play' && ipl.style.display !== 'none' && ip.style.display === 'none');
  tg.click();
  run(0.5);
  check('resume advances 0.5', Math.abs(v() - (p0 + 0.5)) < 0.06 && tg.getAttribute('aria-label') === 'Pause');
  // 3) speed 2x
  pills[3].click();
  var aria = Array.prototype.map.call(pills, function (p) { return p.getAttribute('aria-checked') + (p.classList.contains('is-active') ? '*' : ''); }).join(',');
  var p1 = v();
  run(0.5);
  check('2x speed advances 1.0 in 0.5s [' + aria + ']', Math.abs(v() - (p1 + 1.0)) < 0.08 && aria === 'false,false,false,true*');
  // 4) dt clamp: one giant frame
  var p2 = v();
  window.__pump(5000);
  check('dt clamp (5s frame -> +0.2 at 2x)', Math.abs(v() - (p2 + 0.2)) < 0.01);
  // 5) run to end
  run(5);
  check('ENDED at 8', sc.value === '8' && tg.getAttribute('aria-label') === 'Play' && ipl.style.display !== 'none' && ip.style.display === 'none');
  run(0.5);
  check('ENDED holds', sc.value === '8');
  // 6) toggle in ENDED restarts
  tg.click();
  check('toggle in ENDED -> 0 & playing', v() === 0 && tg.getAttribute('aria-label') === 'Pause');
  run(0.25);
  check('restart advancing (2x)', v() > 0.4 && v() < 0.6 && cd.style.display === 'none');
  // 7) refire hold
  pills[2].click();
  rf.click();
  check('refire -> 0, hidden countdown, pause icon', sc.value === '0' && cd.style.display === 'none' && cd.textContent === '' && tg.getAttribute('aria-label') === 'Pause' && ip.style.display !== 'none');
  run(0.9);
  check('hold keeps 0 at 0.9s', sc.value === '0' && cd.style.display === 'none');
  run(0.3);
  check('playing after hold', v() > 0.1 && v() < 0.3);
  // 8) toggle during hold -> paused at 0
  rf.click();
  run(0.4);
  tg.click();
  run(1.0);
  check('toggle during hold -> paused at 0', sc.value === '0' && tg.getAttribute('aria-label') === 'Play');
  // 9) scrub during hold
  rf.click();
  run(0.3);
  sc.value = '4.5';
  sc.dispatchEvent(new Event('input', { bubbles: true }));
  run(1.5);
  check('scrub during hold -> paused at 4.5', sc.value === '4.5' && tg.getAttribute('aria-label') === 'Play' && cd.style.display === 'none');
  tg.click();
  run(0.5);
  check('play from scrub position', Math.abs(v() - 5.0) < 0.06);
  // 10) determinism: rendering the same time twice yields identical pixels
  var stage = $('stage');
  function grab(t) {
    sc.value = String(t); sc.dispatchEvent(new Event('input', { bubbles: true }));
    var c = document.createElement('canvas'); c.width = 160; c.height = 90;
    var g = c.getContext('2d'); g.drawImage(stage, 0, 0, 160, 90);
    return c.toDataURL();
  }
  var a1 = grab(5.6), b1 = grab(2.0), a2 = grab(5.6);
  var c1 = grab(7.3); rf.click(); run(0.2); var c2 = grab(7.3);
  check('scrub determinism 5.6 == 5.6', a1 === a2);
  check('determinism after refire 7.3 == 7.3', c1 === c2);
  check('Math.random never called by app', window.__mathRandomCalls === 0);
  out.unshift('FAILS: ' + fails + '   errors: ' + window.__errs.length + '  mathRandomCalls=' + window.__mathRandomCalls);
  var pre = document.createElement('pre');
  pre.style.cssText = 'position:fixed;inset:0;margin:0;z-index:2000;background:#000;color:#0f0;font:13px monospace;white-space:pre-wrap;padding:8px';
  pre.textContent = out.join('\n') + '\n' + window.__errs.join('\n');
  document.body.appendChild(pre);
})();

